export function getAllMasterFmcgItems(): MasterFmcgProduct[] {
  return MASTER_FMCG_CATALOG;
}

export function getFmcgCompanies(): string[] {
  const set = new Set<string>();
  for (const item of MASTER_FMCG_CATALOG) {
    if (item.company) set.add(item.company);
  }
  return Array.from(set).sort();
}

export function getFmcgCategories(): string[] {
  const set = new Set<string>();
  for (const item of MASTER_FMCG_CATALOG) {
    if (item.category) set.add(item.category);
  }
  return Array.from(set).sort();
}
